import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,e}from"./app-09e0be14.js";const o={},t=e(`<h1 id="docker-desktop-docker-桌面版图形应用-容器管理" tabindex="-1"><a class="header-anchor" href="#docker-desktop-docker-桌面版图形应用-容器管理" aria-hidden="true">#</a> docker-desktop（Docker 桌面版图形应用（容器管理））</h1><blockquote><p>Homebrew 版本 cask ｜ 主页：见官方文档 ｜ 安装：<code>brew install docker-desktop</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>docker-desktop 是 Docker 官方推出的<strong>桌面版图形应用</strong>，以图形界面（菜单栏图标、Dashboard 面板）管理本地容器与镜像，让普通开发者无需记忆大量 <code>docker</code> 命令也能完成拉取镜像、运行/停止容器、查看日志等日常操作。</p><p>它解决的核心问题是：<strong>在 macOS 上以最省心的方式运行 Docker 引擎</strong>。Docker 依赖 Linux 内核特性（cgroups、namespaces），无法在 macOS 上原生运行，docker-desktop 通过内置的 Linux 虚拟机（HyperKit / Virtualization.framework）在后台静默承载 Docker 引擎，用户只需启动应用即可获得可用的 <code>docker</code> 命令。典型应用场景：本地搭建开发环境、一键运行 MySQL/Redis/Postgres 等中间件、快速验证别人分享的镜像或 compose 工程。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>docker-desktop 是 Homebrew 的 <strong>cask</strong> 类软件（带 GUI 的桌面应用，不是 command-line 类），因此安装、升级、卸载都走 <code>brew install --cask</code> / <code>--cask</code> 一族：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装（cask 安装到 /Applications）</span>
brew <span class="token function">install</span> <span class="token parameter variable">--cask</span> docker-desktop

<span class="token comment"># 升级到最新版（cask 也支持 upgrade）</span>
brew upgrade <span class="token parameter variable">--cask</span> docker-desktop

<span class="token comment"># 卸载</span>
brew uninstall <span class="token parameter variable">--cask</span> docker-desktop

<span class="token comment"># 验证安装：应用已放入应用程序目录</span>
<span class="token function">ls</span> /Applications/Docker.app

<span class="token comment"># 启动应用后（首次会弹出许可协议与初始化向导，需同意并输入系统密码授权内核扩展/虚拟化）</span>
<span class="token function">open</span> <span class="token parameter variable">-a</span> Docker

<span class="token comment"># 等待引擎就绪后再验证 docker 命令是否可用</span>
<span class="token function">docker</span> <span class="token parameter variable">--version</span>
<span class="token function">docker</span> info
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：cask 只安装应用本体，<strong>不自动启动</strong>。第一次需要手动打开 Docker.app 完成初始化，之后引擎才会在后台运行，<code>docker</code> 命令才有响应。</p><p>小技巧：安装后建议立刻执行一次 <code>docker context ls</code>，确认当前 context 是 <code>desktop-linux</code>（Apple Silicon 或新版）还是 <code>default</code>，这决定 <code>docker</code> 命令连的是哪套引擎。</p></blockquote><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><p>docker-desktop 日常使用分两块：一是<strong>图形界面操作</strong>（点菜单栏图标、进 Dashboard），二是<strong>命令行操作</strong>（引擎就绪后就是标准 <code>docker</code> 命令）。以下以命令行为主：</p><table><thead><tr><th>命令</th><th>参数说明</th><th>示例 / 说明</th></tr></thead><tbody><tr><td><code>open -a Docker</code></td><td>启动 Docker 桌面版应用</td><td><code>open -a Docker</code>（也可点 Finder 里的 Docker.app）</td></tr><tr><td><code>docker --version</code></td><td>查看 docker 客户端版本</td><td><code>docker --version</code>（应输出 <code>Docker version 24.x.x</code> 之类）</td></tr><tr><td><code>docker info</code></td><td>查看引擎/守护进程信息，判断是否就绪</td><td><code>docker info</code>（若连接失败说明引擎未启动）</td></tr><tr><td><code>docker ps</code></td><td>列出正在运行的容器</td><td><code>docker ps</code>（加 <code>-a</code> 列出包括已停止的）</td></tr><tr><td><code>docker images</code></td><td>列出本地已有的镜像</td><td><code>docker images</code></td></tr><tr><td><code>docker pull 镜像名</code></td><td>拉取镜像到本地</td><td><code>docker pull nginx:latest</code></td></tr><tr><td><code>docker run -d -p 端口:端口 镜像</code></td><td>运行容器并映射端口</td><td><code>docker run -d -p 8080:80 nginx</code></td></tr><tr><td><code>docker exec -it 容器名 bash</code></td><td>进入容器内的交互式 shell</td><td><code>docker exec -it mynginx bash</code></td></tr><tr><td><code>docker compose up -d</code></td><td>按 compose 文件启动一组容器</td><td><code>docker compose up -d</code>（在工程目录内执行）</td></tr><tr><td><code>docker logs 容器名</code></td><td>查看容器日志</td><td><code>docker logs -f mynginx</code>（<code>-f</code> 持续跟踪）</td></tr><tr><td><code>docker system prune -a</code></td><td>清理无用镜像/容器/缓存，释放磁盘</td><td><code>docker system prune -a</code>（会提示确认）</td></tr></tbody></table><h3 id="更完整的容器生命周期命令" tabindex="-1"><a class="header-anchor" href="#更完整的容器生命周期命令" aria-hidden="true">#</a> 更完整的容器生命周期命令</h3><table><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>docker stop 容器</code> / <code>docker start 容器</code></td><td>停止 / 再次启动（保留容器，数据不丢）</td></tr><tr><td><code>docker restart 容器</code></td><td>重启容器（stop 后再 start）</td></tr><tr><td><code>docker rm -f 容器</code></td><td>删除容器（<code>-f</code> 强制，即使运行中）</td></tr><tr><td><code>docker kill 容器</code></td><td>直接强杀进程（比 stop 更暴力，慎用）</td></tr><tr><td><code>docker pause 容器</code> / <code>docker unpause 容器</code></td><td>暂停 / 恢复进程执行（CPU 被冻结）</td></tr><tr><td><code>docker rename 旧名 新名</code></td><td>给容器改名</td></tr><tr><td><code>docker stats</code></td><td>实时查看各容器 CPU/内存/网络占用（类似 <code>top</code>）</td></tr><tr><td><code>docker inspect 容器</code></td><td>查看容器的底层 JSON 配置、网络 IP、挂载等详细状态</td></tr><tr><td><code>docker port 容器</code></td><td>查看容器的端口映射关系</td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-启动应用并跑起第一个-nginx-容器" tabindex="-1"><a class="header-anchor" href="#示例-1-启动应用并跑起第一个-nginx-容器" aria-hidden="true">#</a> 示例 1：启动应用并跑起第一个 Nginx 容器</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 启动 Docker 桌面版，等待菜单栏的鲸鱼图标变绿（引擎就绪）</span>
<span class="token function">open</span> <span class="token parameter variable">-a</span> Docker

<span class="token comment"># 2. 确认引擎已就绪（能正常输出信息即成功）</span>
<span class="token function">docker</span> info

<span class="token comment"># 3. 拉取官方 nginx 镜像</span>
<span class="token function">docker</span> pull nginx:latest

<span class="token comment"># 4. 以后台方式运行容器，把容器 80 端口映射到本机 8080</span>
<span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">--name</span> mynginx <span class="token parameter variable">-p</span> <span class="token number">8080</span>:80 nginx

<span class="token comment"># 5. 查看运行中的容器</span>
<span class="token function">docker</span> <span class="token function">ps</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：在浏览器打开 <code>http://localhost:8080</code> 就能看到 Nginx 的默认欢迎页，<code>docker ps</code> 里能看到一个名字为 <code>mynginx</code> 的容器。</p><h3 id="示例-2-用-docker-一键启动-mysql-做本地开发" tabindex="-1"><a class="header-anchor" href="#示例-2-用-docker-一键启动-mysql-做本地开发" aria-hidden="true">#</a> 示例 2：用 Docker 一键启动 MySQL 做本地开发</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 启动 MySQL 8 容器，映射 3306 端口，设置 root 密码，并挂载数据卷便于持久化</span>
<span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">--name</span> mymysql <span class="token punctuation">\\</span>
  <span class="token parameter variable">-p</span> <span class="token number">3306</span>:3306 <span class="token punctuation">\\</span>
  <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_ROOT_PASSWORD</span><span class="token operator">=</span>devpass <span class="token punctuation">\\</span>
  <span class="token parameter variable">-e</span> <span class="token assign-left variable">MYSQL_DATABASE</span><span class="token operator">=</span>appdb <span class="token punctuation">\\</span>
  <span class="token parameter variable">-v</span> mysql-data:/var/lib/mysql <span class="token punctuation">\\</span>
  mysql:8

<span class="token comment"># 查看是否启动成功（STATUS 应为 Up）</span>
<span class="token function">docker</span> <span class="token function">ps</span>

<span class="token comment"># 用 mysql 客户端连接验证（没有客户端可用 docker exec 进入容器）</span>
<span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> mymysql mysql <span class="token parameter variable">-uroot</span> <span class="token parameter variable">-pdevpass</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;SHOW DATABASES;&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：登录进去能看到 <code>appdb</code> 等数据库；即使删掉容器（<code>docker rm -f mymysql</code>），数据也保留在 <code>mysql-data</code> 卷里，下次重新 <code>docker run</code> 数据还在。</p><h3 id="示例-3-用-docker-compose-拉起一套-web-redis-环境" tabindex="-1"><a class="header-anchor" href="#示例-3-用-docker-compose-拉起一套-web-redis-环境" aria-hidden="true">#</a> 示例 3：用 docker compose 拉起一套 Web + Redis 环境</h3><p>先在工作目录新建 <code>docker-compose.yml</code>：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">services</span><span class="token punctuation">:</span>
  <span class="token key atrule">web</span><span class="token punctuation">:</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span>latest
    <span class="token key atrule">ports</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token string">&quot;8080:80&quot;</span>
  <span class="token key atrule">cache</span><span class="token punctuation">:</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> redis<span class="token punctuation">:</span><span class="token number">7</span>
    <span class="token key atrule">ports</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token string">&quot;6379:6379&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后在同一目录执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 按 compose 文件在后台启动全部服务</span>
<span class="token function">docker</span> compose up <span class="token parameter variable">-d</span>

<span class="token comment"># 查看服务列表与状态</span>
<span class="token function">docker</span> compose <span class="token function">ps</span>

<span class="token comment"># 跟踪 web 容器日志</span>
<span class="token function">docker</span> compose logs <span class="token parameter variable">-f</span> web

<span class="token comment"># 停止并移除这套环境</span>
<span class="token function">docker</span> compose down
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结果：一条命令同时起好 Nginx 和 Redis 两个容器，且能用 <code>docker compose ps</code> 统一查看状态，适合本地搭多服务开发环境。</p><h3 id="示例-4-进入容器排障并拷贝文件" tabindex="-1"><a class="header-anchor" href="#示例-4-进入容器排障并拷贝文件" aria-hidden="true">#</a> 示例 4：进入容器排障并拷贝文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 进入运行中容器的 shell（缺 bash 时有些精简镜像只有 sh，用 sh）</span>
<span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> mynginx <span class="token function">bash</span>

<span class="token comment"># 容器内操作：查看目录、进程、安装临时工具等</span>
<span class="token comment"># 把容器里的配置文件拷到本机</span>
<span class="token function">docker</span> <span class="token function">cp</span> mynginx:/etc/nginx/nginx.conf ./nginx.conf

<span class="token comment"># 反过来把本机文件拷进容器</span>
<span class="token function">docker</span> <span class="token function">cp</span> ./app.js mynginx:/usr/share/nginx/html/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_5-1-资源限制与调优" tabindex="-1"><a class="header-anchor" href="#_5-1-资源限制与调优" aria-hidden="true">#</a> 5.1 资源限制与调优</h3><p>打开 Docker.app → 顶部菜单栏鲸鱼图标 → Settings → Resources，可调整 <strong>CPUs</strong>（CPU 核数）、<strong>Memory</strong>（内存，默认约 2GB）、<strong>Disk image size</strong>（虚拟磁盘大小，默认约 64GB）。做重活（跑大镜像、多容器）时把内存调到 4GB 以上能显著提速；磁盘空间紧张时可在此调大上限。</p><p>进阶建议：</p><ul><li><strong>用 <code>docker stats</code> 观测实际占用</strong>再决定调多大，别盲目加内存。若发现容器频繁 OOM 被杀死（<code>docker inspect</code> 里 <code>&quot;OOMKilled&quot;: true</code>），再逐步上调 Memory。</li><li><strong>Apple Silicon 上建议至少分配 4GB 内存 + 4 个 CPU</strong>，因为部分镜像（尤其带编译器、Android 构建）在 arm64 仿真 x86 时开销很大。</li><li>资源调整后必须点 <strong>Apply &amp; Restart</strong> 才会重建虚拟机生效。</li></ul><h3 id="_5-2-镜像加速-国内拉取提速" tabindex="-1"><a class="header-anchor" href="#_5-2-镜像加速-国内拉取提速" aria-hidden="true">#</a> 5.2 镜像加速（国内拉取提速）</h3><p>在 Settings → Docker Engine 的 JSON 配置里加入 <code>&quot;registry-mirrors&quot;</code> 字段，填入可用的镜像加速地址（如 DaoCloud、中科大等镜像站），保存并重启 Docker。这会大幅加快 <code>docker pull</code> 的速度：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;registry-mirrors&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token string">&quot;https://docker.m.daocloud.io&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;https://docker.mirrors.ustc.edu.cn&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;https://hub-mirror.c.163.com&quot;</span>
  <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：镜像站经常变动，失效时换一家并 <code>docker system prune</code> 清掉失败缓存；也可装 <code>docker-pull-proxy</code> 类工具做本地代理。</p></blockquote><h3 id="_5-3-docker-engine-常用配置项-daemon-json" tabindex="-1"><a class="header-anchor" href="#_5-3-docker-engine-常用配置项-daemon-json" aria-hidden="true">#</a> 5.3 Docker Engine 常用配置项（daemon.json）</h3><p>Settings → Docker Engine 编辑的是守护进程 <code>daemon.json</code>。除了 <code>registry-mirrors</code>，这些字段也常用：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;registry-mirrors&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;https://docker.m.daocloud.io&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;insecure-registries&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;localhost:5000&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;192.168.1.100:5000&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;log-driver&quot;</span><span class="token operator">:</span> <span class="token string">&quot;json-file&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;log-opts&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;max-size&quot;</span><span class="token operator">:</span> <span class="token string">&quot;10m&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;max-file&quot;</span><span class="token operator">:</span> <span class="token string">&quot;3&quot;</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
  <span class="token property">&quot;default-address-pools&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token punctuation">{</span> <span class="token property">&quot;base&quot;</span><span class="token operator">:</span> <span class="token string">&quot;172.20.0.0/16&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;size&quot;</span><span class="token operator">:</span> <span class="token number">24</span> <span class="token punctuation">}</span>
  <span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;features&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;buildkit&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>各字段含义：</p><table><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td><code>registry-mirrors</code></td><td>镜像加速源，加速 <code>docker pull</code></td></tr><tr><td><code>insecure-registries</code></td><td>允许走 HTTP 的私有仓库（自建 Harbor/Registry），否则拉取会被 TLS 拦截</td></tr><tr><td><code>log-driver</code> / <code>log-opts</code></td><td>限制容器日志大小，防止日志无限膨胀撑爆磁盘（<code>max-size</code>+<code>max-file</code>）</td></tr><tr><td><code>default-address-pools</code></td><td>自定义容器网段的网段池，避免与公司内网/VPN 网段冲突</td></tr><tr><td><code>features.buildkit</code></td><td>开启 BuildKit（新版默认开），让 <code>docker build</code> 更快、支持 <code>RUN --mount</code> 缓存</td></tr></tbody></table><p>改完记得 Apply &amp; Restart 生效。</p><h3 id="_5-4-配置与数据位置" tabindex="-1"><a class="header-anchor" href="#_5-4-配置与数据位置" aria-hidden="true">#</a> 5.4 配置与数据位置</h3><p>docker-desktop 的引擎数据、镜像、卷都存放在其内置虚拟磁盘（<code>~/Library/Containers/com.docker.docker</code> 下）中，而非系统根目录，卸载应用或清理时不需担心污染磁盘根分区。日常的 <code>docker</code> 配置（daemon.json、注册表登录态）也由应用统一管理，命令行里改完需在应用里重启引擎生效。</p><ul><li>登录镜像仓库状态：<code>docker login</code> 后凭证存于 <code>~/.docker/config.json</code>。</li><li>清理虚拟磁盘空间：除了 <code>docker system prune</code>，还可在 Settings → Resources → Troubleshoot → <strong>Clean / Purge data</strong> 彻底重置（会清空所有镜像、卷、容器）。</li></ul><h3 id="_5-5-与其它工具搭配" tabindex="-1"><a class="header-anchor" href="#_5-5-与其它工具搭配" aria-hidden="true">#</a> 5.5 与其它工具搭配</h3><ul><li>与 <code>docker compose</code>（v2 已内置）搭配编排多容器工程，是开发环境标配；</li><li>与 <code>docker-compose</code> 的旧版脚本配合：旧工程可 <code>brew install docker-compose</code>，新工程优先用内置的 <code>docker compose</code> 子命令；</li><li>配合 VS Code 的 Docker 插件，可在编辑器里可视化浏览镜像、容器并右键启停，图形界面与命令行互补；</li><li>与 <code>lsof</code>/<code>nc</code> 排查端口冲突：先 <code>lsof -nP -iTCP:8080 -sTCP:LISTEN</code> 看端口被谁占用，再决定是否调整 <code>-p</code> 映射；</li><li>与 <code>docker-completion</code>（bash/zsh 自动补全）配合：<code>brew install docker-completion</code>，配好后敲 <code>docker &lt;Tab&gt;</code> 能补全命令、镜像名、容器名，大幅减少手打；</li><li>与 <code>jq</code> 配合解析 <code>docker inspect</code> 的 JSON 输出：<code>docker inspect mynginx | jq &#39;.[0].NetworkSettings.IPAddress&#39;</code> 快速取容器 IP。</li></ul><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ol><li><p><strong>必须启动 Docker.app 后引擎才可用</strong>：<code>docker</code> 命令单独安装/升级 cask 不会自动拉起守护进程。出现 <code>Cannot connect to the Docker daemon</code> 或 <code>connection refused</code> 时，先打开 Docker.app 等菜单栏图标变绿再重试。</p></li><li><p><strong>首次启动需要授权与许可</strong>：第一次打开 Docker.app 会弹「Accept terms」（接受许可）、询问是否安装内核扩展/使用虚拟化，需要输入 macOS 管理员密码并允许。若被系统拒绝或安装失败，通常在系统设置 → 隐私与安全里允许对应扩展后重启应用即可。</p></li><li><p><strong>Windows 老镜像或架构不匹配</strong>：macOS（Apple Silicon 或 Intel）默认按本机架构拉镜像。碰到提示 <code>no matching manifest for linux/amd64</code> 或无法运行 x86 镜像时，可在 Docker Desktop Settings → Docker Engine 的 JSON 里加上 <code>&quot;platform&quot;: &quot;linux/amd64&quot;</code> 或改用 <code>docker run --platform linux/amd64</code> 显式指定架构。</p></li><li><p><strong>磁盘占用增长很快</strong>：镜像、卷、日志累积会让内置虚拟磁盘膨胀，导致 macOS 磁盘空间报警。定期用 <code>docker system prune -a</code>（慎用 <code>-a</code>，会删所有未使用的镜像）清理，或在 Settings → Resources 查看并调整 Disk image size。</p></li><li><p><strong>端口映射冲突</strong>：<code>docker run -p 8080:80</code> 如果 8080 已被本机其它程序占用，会报 <code>port is already allocated</code>。先用 <code>lsof -nP -iTCP:8080 -sTCP:LISTEN</code> 查占用，换一个端口或停掉占用程序再重试。</p></li><li><p><strong>数据要挂卷持久化</strong>：容器一旦删除，未挂卷的数据会随之丢失。重要数据（数据库、上传文件）务必用 <code>-v 卷名:容器路径</code> 挂卷，避免 <code>docker rm</code> 后数据消失。</p></li><li><p><strong>引擎重启后资源设置生效</strong>：在 Settings 里改 CPU/内存/磁盘后需要点「Apply &amp; Restart」重启引擎才生效；重启期间所有容器会中断，请避免在生产式任务中直接重启。</p></li><li><p><strong>Apple Silicon 的 x86 镜像慢到怀疑人生</strong>：用 <code>--platform linux/amd64</code> 跑 x86 镜像会走 Rosetta 仿真，性能骤降、内存暴涨。优先找 arm64 官方多架构镜像（<code>--platform linux/arm64</code>），能省一半时间。</p></li><li><p><strong>容器里访问宿主机服务</strong>：新版用 <code>host.docker.internal</code> 指向宿主机的 <code>localhost</code>，而不是老的 <code>docker.for.mac.host.internal</code>。容器内连接宿主 MySQL 用 <code>host.docker.internal:3306</code>。</p></li><li><p><strong>DNS / 网络连不上外网</strong>：公司网络有代理或 DNS 污染时，容器可能解析不了域名。在 Settings → Resources → Proxies 配置 HTTP/HTTPS 代理，或在 daemon.json 里给容器配置固定 DNS <code>&quot;dns&quot;: [&quot;8.8.8.8&quot;, &quot;114.114.114.114&quot;]</code>。</p></li><li><p><strong><code>docker</code> 命令权限/未找到</strong>：确认 <code>/usr/local/bin</code> 或 <code>/opt/homebrew/bin</code> 在 PATH 里，且 cask 版本正常。若提示 <code>command not found: docker</code>，重装 cask 或 <code>brew link docker</code> 修复。</p></li><li><p><strong>升级后引擎起不来 / 一直转圈</strong>：多为旧版本数据不兼容或磁盘文件损坏。先备份卷数据，再到 Settings → Troubleshoot → Restart / Reset to factory defaults 重置；仍不行就彻底卸载重装 cask。</p></li></ol><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_7-1-用-makefile-封装常用命令" tabindex="-1"><a class="header-anchor" href="#_7-1-用-makefile-封装常用命令" aria-hidden="true">#</a> 7.1 用 Makefile 封装常用命令</h3><p>把反复敲的命令收进 <code>Makefile</code>，一键完成「起环境、看状态、进容器、清理」：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile（放在工程根目录，与 docker-compose.yml 同级）</span>
<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> up down logs shell clean ps pull build

<span class="token target symbol">up</span><span class="token punctuation">:</span>            <span class="token comment">## 后台启动整套环境</span>
	docker compose up -d

<span class="token target symbol">down</span><span class="token punctuation">:</span>          <span class="token comment">## 停止并移除整套环境</span>
	docker compose down

<span class="token target symbol">ps</span><span class="token punctuation">:</span>            <span class="token comment">## 查看服务状态</span>
	docker compose ps

<span class="token target symbol">logs</span><span class="token punctuation">:</span>          <span class="token comment">## 跟踪全部服务日志</span>
	docker compose logs -f

<span class="token target symbol">shell</span><span class="token punctuation">:</span>         <span class="token comment">## 进入 web 容器 shell</span>
	docker compose exec web bash

<span class="token target symbol">pull</span><span class="token punctuation">:</span>          <span class="token comment">## 拉取并更新镜像</span>
	docker compose pull

<span class="token target symbol">build</span><span class="token punctuation">:</span>         <span class="token comment">## 重新构建镜像</span>
	docker compose build --pull

<span class="token target symbol">clean</span><span class="token punctuation">:</span>         <span class="token comment">## 清理无用镜像/缓存/卷</span>
	docker system prune -a --volumes
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用法：<code>make up</code>、<code>make logs</code>、<code>make clean</code> 即可，团队协作时还能统一命令习惯。</p><h3 id="_7-2-与-docker-compose-的高级编排" tabindex="-1"><a class="header-anchor" href="#_7-2-与-docker-compose-的高级编排" aria-hidden="true">#</a> 7.2 与 docker compose 的高级编排</h3><p>生产级 compose 常带环境变量、健康检查、依赖顺序和资源限制：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">services</span><span class="token punctuation">:</span>
  <span class="token key atrule">db</span><span class="token punctuation">:</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> postgres<span class="token punctuation">:</span><span class="token number">16</span>
    <span class="token key atrule">environment</span><span class="token punctuation">:</span> <span class="token important">&amp;pg_env</span>
      <span class="token key atrule">POSTGRES_USER</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>POSTGRES_USER<span class="token punctuation">:</span><span class="token punctuation">-</span>app<span class="token punctuation">}</span>
      <span class="token key atrule">POSTGRES_PASSWORD</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>POSTGRES_PASSWORD<span class="token punctuation">:</span><span class="token punctuation">-</span>secret<span class="token punctuation">}</span>
      <span class="token key atrule">POSTGRES_DB</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>POSTGRES_DB<span class="token punctuation">:</span><span class="token punctuation">-</span>appdb<span class="token punctuation">}</span>
    <span class="token key atrule">volumes</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> pgdata<span class="token punctuation">:</span>/var/lib/postgresql/data
    <span class="token key atrule">healthcheck</span><span class="token punctuation">:</span>
      <span class="token key atrule">test</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;CMD-SHELL&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;pg_isready -U app&quot;</span><span class="token punctuation">]</span>
      <span class="token key atrule">interval</span><span class="token punctuation">:</span> 5s
      <span class="token key atrule">timeout</span><span class="token punctuation">:</span> 3s
      <span class="token key atrule">retries</span><span class="token punctuation">:</span> <span class="token number">5</span>
    <span class="token key atrule">deploy</span><span class="token punctuation">:</span>
      <span class="token key atrule">resources</span><span class="token punctuation">:</span>
        <span class="token key atrule">limits</span><span class="token punctuation">:</span>
          <span class="token key atrule">memory</span><span class="token punctuation">:</span> 1g

  <span class="token key atrule">web</span><span class="token punctuation">:</span>
    <span class="token key atrule">build</span><span class="token punctuation">:</span> .
    <span class="token key atrule">ports</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token string">&quot;8080:80&quot;</span>
    <span class="token key atrule">depends_on</span><span class="token punctuation">:</span>
      <span class="token key atrule">db</span><span class="token punctuation">:</span>
        <span class="token key atrule">condition</span><span class="token punctuation">:</span> service_healthy
    <span class="token key atrule">environment</span><span class="token punctuation">:</span>
      <span class="token key atrule">DATABASE_URL</span><span class="token punctuation">:</span> postgres<span class="token punctuation">:</span>//app<span class="token punctuation">:</span>secret@db<span class="token punctuation">:</span>5432/appdb

<span class="token key atrule">volumes</span><span class="token punctuation">:</span>
  <span class="token key atrule">pgdata</span><span class="token punctuation">:</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>docker compose up -d --wait</code> 会等所有 <code>healthcheck</code> 通过后才返回，方便脚本里判断就绪。</p><h3 id="_7-3-环境变量与多环境切换" tabindex="-1"><a class="header-anchor" href="#_7-3-环境变量与多环境切换" aria-hidden="true">#</a> 7.3 环境变量与多环境切换</h3><p>用 <code>.env</code> 文件区分开发/测试/生产，配合 compose 的 <code>\${VAR}</code> 插值：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># .env（开发环境）</span>
<span class="token assign-left variable">POSTGRES_USER</span><span class="token operator">=</span>dev
<span class="token assign-left variable">POSTGRES_PASSWORD</span><span class="token operator">=</span>devpass
<span class="token assign-left variable">TAG</span><span class="token operator">=</span>latest

<span class="token comment"># .env.prod（生产）</span>
<span class="token assign-left variable">POSTGRES_USER</span><span class="token operator">=</span>prod
<span class="token assign-left variable">POSTGRES_PASSWORD</span><span class="token operator">=</span>supersecret
<span class="token assign-left variable">TAG</span><span class="token operator">=</span>v1.2.0
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 按环境加载（compose 自动读取同目录 .env，也可显式指定）</span>
<span class="token function">docker</span> compose --env-file .env.prod up <span class="token parameter variable">-d</span>
<span class="token function">docker</span> compose --env-file .env.prod <span class="token function">ps</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-ci-集成-github-actions-gitlab-ci" tabindex="-1"><a class="header-anchor" href="#_7-4-ci-集成-github-actions-gitlab-ci" aria-hidden="true">#</a> 7.4 CI 集成（GitHub Actions / GitLab CI）</h3><p>Docker 命令可直接放进 CI 脚本，用 <code>--platform</code>、<code>-f</code>、<code>--env-file</code> 保持与本地一致：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/ci.yml 片段</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">build</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build image
        <span class="token key atrule">run</span><span class="token punctuation">:</span> docker compose <span class="token punctuation">-</span>f docker<span class="token punctuation">-</span>compose.yml build <span class="token punctuation">-</span><span class="token punctuation">-</span>pull
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Smoke test
        <span class="token key atrule">run</span><span class="token punctuation">:</span> docker compose up <span class="token punctuation">-</span>d <span class="token punctuation">-</span><span class="token punctuation">-</span>wait <span class="token important">&amp;&amp;</span> curl <span class="token punctuation">-</span>fsS http<span class="token punctuation">:</span>//localhost<span class="token punctuation">:</span><span class="token number">8080</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Push to registry
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          echo &quot;\${{ secrets.DOCKER_PASSWORD }}&quot; | docker login -u &quot;\${{ secrets.DOCKER_USER }}&quot; --password-stdin
          docker compose push</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-5-批量处理-循环-常用批量命令" tabindex="-1"><a class="header-anchor" href="#_7-5-批量处理-循环-常用批量命令" aria-hidden="true">#</a> 7.5 批量处理：循环 + 常用批量命令</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 批量停止/删除所有容器（开发环境一键清场）</span>
<span class="token function">docker</span> <span class="token function">ps</span> <span class="token parameter variable">-q</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-r</span> <span class="token function">docker</span> stop
<span class="token function">docker</span> <span class="token function">ps</span> <span class="token parameter variable">-aq</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-r</span> <span class="token function">docker</span> <span class="token function">rm</span>

<span class="token comment"># 批量清理悬空镜像（&lt;none&gt; 镜像）</span>
<span class="token function">docker</span> images <span class="token parameter variable">-q</span> <span class="token parameter variable">-f</span> <span class="token assign-left variable">dangling</span><span class="token operator">=</span>true <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-r</span> <span class="token function">docker</span> rmi

<span class="token comment"># 批量移除卷（仅当确认无用！）</span>
<span class="token function">docker</span> volume <span class="token function">ls</span> <span class="token parameter variable">-q</span> <span class="token parameter variable">-f</span> <span class="token assign-left variable">dangling</span><span class="token operator">=</span>true <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-r</span> <span class="token function">docker</span> volume <span class="token function">rm</span>

<span class="token comment"># 批量给所有运行容器打标签</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">c</span> <span class="token keyword">in</span> <span class="token variable"><span class="token variable">$(</span><span class="token function">docker</span> <span class="token function">ps</span> <span class="token parameter variable">-q</span><span class="token variable">)</span></span><span class="token punctuation">;</span> <span class="token keyword">do</span> <span class="token function">docker</span> commit <span class="token string">&quot;<span class="token variable">$c</span>&quot;</span> <span class="token string">&quot;backup-<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d<span class="token variable">)</span></span>&quot;</span><span class="token punctuation">;</span> <span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>批量命令很危险，先 <code>echo</code> 预览要处理的对象，确认无误再去掉 <code>xargs</code> 前的 <code>-r</code> 保护或换成实际执行。</p></blockquote><h3 id="_7-6-生产级实践要点" tabindex="-1"><a class="header-anchor" href="#_7-6-生产级实践要点" aria-hidden="true">#</a> 7.6 生产级实践要点</h3><ul><li><strong>日志一定要限流</strong>：在 daemon.json 配 <code>log-opts.max-size=10m</code>，否则容器无限写日志会撑爆虚拟磁盘，CI 里尤其容易触发。</li><li><strong>镜像体积</strong>：多用多阶段构建（multi-stage build）、<code>.dockerignore</code> 排除 <code>node_modules</code>、<code>dist</code>、<code>.git</code>；小镜像用 alpine 或 distroless。</li><li><strong>版本固定</strong>：<code>docker pull postgres:16</code>、compose 里锁死 tag 或摘要（<code>image: postgres@sha256:...</code>），避免上游更新打破生产。</li><li><strong>机密安全</strong>：密码/密钥别硬编码进 Dockerfile，用环境变量、<code>.env</code>（不入 git）、或 Docker Desktop 的 Secret 功能 / 密钥管理器注入。</li><li><strong>数据可回滚</strong>：数据库镜像挂命名卷，升级前先 <code>docker compose exec db pg_dump -U app appdb &gt; backup.sql</code> 或快照卷，便于回滚。</li></ul><h3 id="_7-7-一键备份与恢复-shell-脚本" tabindex="-1"><a class="header-anchor" href="#_7-7-一键备份与恢复-shell-脚本" aria-hidden="true">#</a> 7.7 一键备份与恢复（shell 脚本）</h3><p>把「起环境→备份→清理」串成脚本，支持命令行参数：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token comment"># backup-docker.sh —— 备份所有命名卷数据到当前目录 tar 包</span>
<span class="token builtin class-name">set</span> <span class="token parameter variable">-euo</span> pipefail
<span class="token assign-left variable">STAMP</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d_%H%M%S<span class="token variable">)</span></span>&quot;</span>
<span class="token assign-left variable">OUT</span><span class="token operator">=</span><span class="token string">&quot;docker-volumes-<span class="token variable">\${STAMP}</span>.tar&quot;</span>
<span class="token comment"># 1. 临时起一个挂载全部命名卷的 alpine 容器</span>
<span class="token assign-left variable">VOLS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">docker</span> volume <span class="token function">ls</span> <span class="token parameter variable">-q</span><span class="token variable">)</span></span>
<span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$VOLS</span>&quot;</span> <span class="token punctuation">]</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">{</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;没有卷可备份&quot;</span><span class="token punctuation">;</span> <span class="token builtin class-name">exit</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment"># 2. 逐个导出</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">vol</span> <span class="token keyword">in</span> <span class="token variable">$VOLS</span><span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token function">docker</span> run <span class="token parameter variable">--rm</span> <span class="token parameter variable">-v</span> <span class="token string">&quot;<span class="token variable">\${vol}</span>:/data&quot;</span> <span class="token parameter variable">-v</span> <span class="token string">&quot;<span class="token environment constant">$PWD</span>:/backup&quot;</span> alpine <span class="token punctuation">\\</span>
    <span class="token function">tar</span> czf <span class="token string">&quot;/backup/<span class="token variable">\${vol}</span>-<span class="token variable">\${STAMP}</span>.tgz&quot;</span> <span class="token parameter variable">-C</span> /data <span class="token builtin class-name">.</span>
<span class="token keyword">done</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;已备份到：<span class="token environment constant">$PWD</span> 下的 *_<span class="token variable">\${STAMP}</span>.tgz&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>恢复：<code>docker volume create myvol</code> 后 <code>docker run --rm -v myvol:/data -v $PWD:/backup alpine tar xzf /backup/myvol-xxx.tgz -C /data</code>。</p>`,76),c=[t];function p(l,i){return s(),a("div",null,c)}const u=n(o,[["render",p],["__file","docker-desktop.html.vue"]]);export{u as default};
